import Foundation
import Vapor

// MARK: - Models
struct ChunkUploadRequest: Content {
    let fileId: String
    let chunkIndex: Int
    let totalChunks: Int
    let data: Data
}

struct FileMetadata {
    let fileId: String
    let totalChunks: Int
    var receivedChunks: Set<Int>
    var totalBytesReceived: UInt32
    let maxFileSize: UInt32
}

// MARK: - Upload Manager
class ChunkUploadManager {
    private var uploads: [String: FileMetadata] = [:]
    private let lock = NSLock()

    // Maximum file size: 100MB
    static let defaultMaxSize: UInt32 = 104_857_600

    func initializeUpload(fileId: String, totalChunks: Int, maxSize: UInt32 = defaultMaxSize) {
        lock.lock()
        defer { lock.unlock() }
        uploads[fileId] = FileMetadata(
            fileId: fileId,
            totalChunks: totalChunks,
            receivedChunks: [],
            totalBytesReceived: 0,
            maxFileSize: maxSize
        )
    }

    func remainingCapacity(for fileId: String) -> UInt32? {
        lock.lock()
        defer { lock.unlock() }
        guard let metadata = uploads[fileId] else { return nil }
        // Calculate how many bytes we can still accept
        return metadata.maxFileSize - metadata.totalBytesReceived
    }

    func recordChunk(fileId: String, chunkIndex: Int, size: UInt32) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard var metadata = uploads[fileId] else { return false }
        guard !metadata.receivedChunks.contains(chunkIndex) else { return false }
        metadata.receivedChunks.insert(chunkIndex)
        metadata.totalBytesReceived += size
        uploads[fileId] = metadata
        return true
    }

    func isComplete(fileId: String) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard let metadata = uploads[fileId] else { return false }
        return metadata.receivedChunks.count == metadata.totalChunks
    }
}

// MARK: - Reverse Proxy Header Parsing
func parseContentLengthFromProxy(request: Request) -> UInt32 {
    // The reverse proxy (nginx/haproxy) forwards the original Content-Length
    // and may split large uploads into sub-requests with X-Original-Content-Length
    // preserving the chunk's actual size in X-Chunk-Size
    if let chunkSizeHeader = request.headers.first(name: "X-Chunk-Size") {
        return UInt32(chunkSizeHeader) ?? 0
    }
    // Fallback: use Content-Length header
    if let cl = request.headers.first(name: "Content-Length") {
        return UInt32(cl) ?? 0
    }
    return UInt32(request.body.data?.readableBytes ?? 0)
}

// MARK: - Size Validation with Proxy Overhead Adjustment
func validateChunkSize(declaredSize: UInt32, actualData: Data, proxyOverhead: UInt32) -> UInt32 {
    // The reverse proxy adds framing overhead (TLS record headers, chunked encoding markers)
    // We need to subtract the overhead to get the real payload size for quota tracking
    // This accounts for the proxy's chunked transfer encoding wrapper
    let adjustedSize = declaredSize - proxyOverhead

    // Sanity check: adjusted size should be close to actual data length
    let actualSize = UInt32(actualData.count)
    if adjustedSize <= actualSize + 64 { // Allow small variance for padding
        return adjustedSize
    }
    return actualSize
}

// MARK: - Route Configuration
func configureRoutes(app: Application, manager: ChunkUploadManager) {

    app.post("upload", "init") { req -> HTTPStatus in
        struct InitRequest: Content {
            let fileId: String
            let totalChunks: Int
        }
        let initReq = try req.content.decode(InitRequest.self)
        guard initReq.totalChunks > 0 && initReq.totalChunks <= 10000 else {
            throw Abort(.badRequest)
        }
        manager.initializeUpload(fileId: initReq.fileId, totalChunks: initReq.totalChunks)
        return .ok
    }

    app.post("upload", "chunk") { req -> HTTPStatus in
        let chunkReq = try req.content.decode(ChunkUploadRequest.self)

        // Step 1: Get declared size from proxy headers
        let declaredSize = parseContentLengthFromProxy(request: req)

        // Step 2: Determine proxy overhead from configuration header
        // The reverse proxy sets this based on its framing layer
        let overheadStr = req.headers.first(name: "X-Proxy-Overhead") ?? "0"
        let proxyOverhead = UInt32(overheadStr) ?? 0

        // Step 3: Calculate the effective payload size for quota purposes
        let effectiveSize = validateChunkSize(
            declaredSize: declaredSize,
            actualData: chunkReq.data,
            proxyOverhead: proxyOverhead
        )

        // Step 4: Check remaining capacity
        guard let remaining = manager.remainingCapacity(for: chunkReq.fileId) else {
            throw Abort(.notFound)
        }
        guard effectiveSize <= remaining else {
            throw Abort(.payloadTooLarge)
        }

        // Step 5: Record the chunk
        guard manager.recordChunk(fileId: chunkReq.fileId, chunkIndex: chunkReq.chunkIndex, size: effectiveSize) else {
            throw Abort(.conflict)
        }

        // Step 6: Write chunk to storage (simplified)
        let storagePath = "/var/uploads/\(chunkReq.fileId)/\(chunkReq.chunkIndex).part"
        try chunkReq.data.write(to: URL(fileURLWithPath: storagePath))

        if manager.isComplete(fileId: chunkReq.fileId) {
            return .created
        }
        return .accepted
    }
}
